window.STATION_PARTS=window.STATION_PARTS||{};
window.STATION_PARTS["aire"]={"id":"aire","title":"Air conditioning and pneumatic","color":"#55687A","stations":[
{"id":"air-1","subject":"aire","order":1,"kind":"lesson","level":1,"ident":"AIR","title":"Air systems at a glance","goal":"Explicar de dónde sale el aire del avión, para qué se usa y cómo llega a la cabina, se presuriza y se ventila.","intro":"Empezamos por el panorama: de dónde sale el aire, quién lo usa y cómo termina en la cabina.","minutes":6,"cards":[{"id":"air-1-c1","title":"Three air sources","body":"El sistema neumático entrega aire a alta presión. Tiene tres fuentes:\n- el **bleed** de los dos motores;\n- el **APU** (su load compressor);\n- una **conexión de tierra** de alta presión (HP).\n\nUn **crossbleed duct** une el lado del motor 1 con el del motor 2, y recibe el aire del APU o de tierra. Una **crossbleed valve** deja unir o separar los dos lados. Dos computadores, los **BMC** (Bleed Monitoring Computers), controlan y vigilan el sistema.","diagram":{"alt":"Esquema del sistema neumático: el bleed del motor 1 y del motor 2, unidos por el crossbleed duct con su crossbleed valve; el APU y la conexión de tierra HP entran al duct; abajo, los usuarios: packs, arranque de motores, wing anti-ice y otros.","src":"assets/estaciones/diagramas/air-fuentes.svg"},"keyIdea":"Tres fuentes: bleed de los motores, APU y tierra HP; el crossbleed une los dos lados."},{"id":"air-1-c2","title":"Who uses the air","body":"El aire neumático se usa para:\n- el aire acondicionado (los packs);\n- el arranque de los motores;\n- el wing anti-ice;\n- presurizar el agua potable y los reservorios hidráulicos;\n- calefacción de bodega y el sistema de inertización de combustible, en los aviones que los tienen.","keyIdea":"Packs, arranque de motores, wing anti-ice, agua y reservorios hidráulicos."},{"id":"air-1-c3","title":"From the packs to the cabin","body":"El aire del bleed entra a los **dos packs** por sus **pack flow control valves**. Los packs lo enfrían y lo mandan a la **mixing unit**, que lo mezcla con aire de la cabina que traen los **recirculation fans**. De ahí se reparte al cockpit y a la cabina.\n\nPor eso el aire de la cabina es una mezcla de bleed (de los motores o, si se elige, del APU) y aire recirculado.","keyIdea":"Bleed → packs → mixing unit (con aire recirculado) → cockpit y cabina."},{"id":"air-1-c4","title":"Three temperature zones","body":"El aire acondicionado es totalmente automático y mantiene la temperatura elegida en **tres zonas**, cada una con su control: **COCKPIT**, **FWD CABIN** y **AFT CABIN**. En el panel AIR COND hay un selector de temperatura para cada zona.\n\nLa presurización la hace una **outflow valve** que deja salir aire de la cabina, comandada por dos controladores; dos **safety valves** protegen la estructura. La aviónica tiene su propia ventilación.","keyIdea":"Tres zonas con su selector; la outflow valve presuriza; la aviónica tiene su ventilación."}],"test":[{"id":"air-1-t1","type":"mcq","question":"WHAT ARE THE DIFFERENT SOURCES OF AIR FOR AIR CONDITIONING AND PRESSURIZATION?","options":["ENGINE BLEED AIR.","ENGINE BLEED AIR AND RECIRCULATED AIR.","ENGINE BLEED AIR AND RECIRCULATED AIR, OR IF SELECTED, APU BLEED AIR AND RECIRCULATED AIR.","NONE OF THE ABOVE."],"correct":2,"explanation":"Las fuentes de aire para climatización y presurización son el bleed de motor combinado con aire recirculado, o si se selecciona, el bleed del APU combinado con aire recirculado.","taughtIn":["air-1-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:p1x8mo"}},{"id":"air-1-t2","type":"mcq","question":"RECIRCULATION FANS IN THE AIR CONDITIONING SYSTEM DIRECT FILTERED CABIN AIR TO WHICH AREA?","options":["THE PNEUMATIC DUCK, UPSTREAM OF THE PACKS.","THE AVIONICS COMPARTMENT.","THE MIXING UNIT."],"correct":2,"explanation":"Los ventiladores de recirculación dirigen el aire filtrado de cabina hacia la mixing unit, donde se combina con el aire fresco proveniente de los packs.","taughtIn":["air-1-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:t9bxx6"}},{"id":"air-1-t3","type":"mcq","question":"¿Qué hace la mixing unit del sistema de aire acondicionado?","options":["Mezcla aire recirculado con aire de los packs","Mezcla exclusivamente bleed de ambos motores","Separa el aire caliente del aire frío antes de los packs","Regula la presión de cabina mediante el outflow valve"],"correct":0,"explanation":"La mixing unit mezcla el aire frío de los packs con el aire de la cabina que traen los recirculation fans; de ahí se reparte al cockpit y a la cabina.","taughtIn":["air-1-c3"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:ls1urc"}},{"id":"air-1-t4","type":"mcq","question":"¿Cómo está organizado el control de temperatura del aire acondicionado del A320?","options":["En una sola zona para toda la aeronave","Tres zonas: cockpit, forward cabin y aft cabin","En dos zonas: cockpit y cabin","En cuatro zonas independientes en todos los aviones"],"correct":1,"explanation":"El sistema mantiene una temperatura seleccionada en tres zonas independientes. La separación permite que cockpit, cabina delantera y cabina trasera tengan demandas térmicas distintas sin obligar a que toda la aeronave use un único ajuste.","taughtIn":["air-1-c4"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1az714v"}},{"id":"air-1-t5","type":"mcq","question":"HOW MANY TEMPERATURE SELECTORS ARE THERE ON THE A-320? HOW MANY TEMPERATURE ZONES ARE THERE?","options":["THREE ROTARY TEMPERATURE SELECTORS AND ONE ZONE.","THREE ROTARY TEMPRERATURE SELECTORS, ONE EACH FOR THE COCKPIT ZONE, THE FORWARD CABIN ZONE, AND THE AFT CABIN ZONE.","TWO ROTARY TEMPERATURE SELECTORS, ONE FOR THE COCKPIT AND FIRST CLASS ZONE AND ONE FOR THE AFT CABIN ZONE.","FOUR ROTARY TEMPERATURE SELECTORS AND FOUR ZONES."],"correct":1,"explanation":"El A320 tiene tres selectores rotativos de temperatura, uno para cada una de las tres zonas: cockpit, cabina delantera, y cabina trasera.","taughtIn":["air-1-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:16zv5kb"}}]},
{"id":"air-2","subject":"aire","order":2,"kind":"lesson","level":1,"ident":"BLD","title":"Engine bleed","goal":"Explicar de qué etapa del motor sale el bleed, cómo se regula su presión y su temperatura y qué cierra la bleed valve.","intro":"El aire de los motores no sale de cualquier parte: el sistema elige la etapa, regula la presión y lo enfría antes de usarlo.","minutes":6,"cards":[{"id":"air-2-c1","title":"IP or HP stage","body":"Normalmente el aire sale de la etapa de **presión intermedia (IP)** del compresor del motor, para gastar menos combustible. A baja potencia, cuando el aire de la etapa IP no tiene suficiente presión ni temperatura, el sistema toma aire de la etapa de **alta presión (HP)** por la **HP valve**.\n\nUna check valve después de la salida IP impide que el aire de la etapa HP vuelva hacia la etapa IP.","diagram":{"alt":"Un motor con su salida IP (con check valve) y su salida HP (con HP valve); las dos se unen antes de la bleed valve, que regula la presión; después, la overpressure valve y el precooler, enfriado con aire del fan.","src":"assets/estaciones/diagramas/air-bleed.svg"},"keyIdea":"IP en lo normal; HP a baja potencia; la check valve impide que el HP vuelva al IP."},{"id":"air-2-c2","title":"The bleed valve","body":"La **bleed valve**, después de la unión de IP y HP, corta el paso y además **regula la presión**:\n- en la mayoría de los A320, mantiene unos **45 PSI** (± 5);\n- en los A320neo, unos 42 PSI con los dos bleeds y unos 50 PSI con uno solo.\n\nSi la regulación falla, una **overpressure valve** cierra cuando la presión pasa de unos 75 u 80 PSI, según el avión. Como las demás válvulas del bleed, la bleed valve es de **accionamiento neumático y control eléctrico**: la mueve el aire y la comanda su BMC.","keyIdea":"La bleed valve regula la presión (unos 45 PSI); la overpressure valve es el respaldo."},{"id":"air-2-c3","title":"The precooler","body":"Después de la bleed valve, un **precooler** regula la temperatura del bleed a unos **200 °C**. Es un intercambiador de calor aire-aire que usa **aire del fan** del motor; una fan air valve regula cuánto aire del fan pasa.","keyIdea":"El precooler enfría el bleed con aire del fan, a unos 200 °C."},{"id":"air-2-c4","title":"What closes the bleed valve","body":"La bleed valve se cierra:\n- **en forma neumática:** si la presión que llega del motor es muy baja, o si hay flujo de retorno (reverse flow);\n- **por orden eléctrica:** con el botón ENG BLEED en OFF, al presionar el ENG FIRE pb, o por el BMC ante sobretemperatura, sobrepresión, fuga, starter valve abierta o APU BLEED en ON, entre otras.\n\nSin presión de aire, queda cerrada. Si un BMC falla, el otro toma la mayor parte de la vigilancia; pero la bleed valve de ese lado ya no se cierra sola ante una falla.","keyIdea":"Cierra por baja presión o reverse flow, con el botón, el ENG FIRE pb o el BMC."}],"test":[{"id":"air-2-t1","type":"mcq","question":"BLEED AIR NORMALLY COMES FROM THE ________ OF THE ENGINE.","options":["HIGH PRESSURE STAGE.","INTERMEDIATE STAGE.","LOW PRESSURE STAGE."],"correct":1,"explanation":"El aire sangrado proviene normalmente de la etapa intermedia (intermediate stage) del motor; la etapa de alta presión se usa como respaldo cuando la presión intermedia no es suficiente, por ejemplo en ralentí.","taughtIn":["air-2-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1ksetnf"}},{"id":"air-2-t2","type":"mcq","question":"ENGINE BLEED AIR TEMPERATURE IS CONTROLLED BY:","options":["ENGINE OIL.","A PRE-COOLER THAT USES FAN AIR.","CONDITIONED AIR FROM THE MIXING UNIT."],"correct":1,"explanation":"La temperatura del aire sangrado del motor se controla mediante un precooler que usa aire de fan, no mediante el aceite del motor ni con aire condicionado de la mixing unit.","taughtIn":["air-2-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1x02q3q"}},{"id":"air-2-t3","type":"mcq","question":"Si la presión aguas arriba de una engine bleed valve cae demasiado o aparece reverse flow, ¿qué hace la válvula?","options":["Cierra para proteger/aislar la fuente","Abre completamente para recuperar presión","Mantiene la última posición hasta una orden manual","Transfiere automáticamente el control a la wing anti-ice valve"],"correct":0,"explanation":"La engine bleed valve no debe permitir flujo inverso ni una fuente neumática inadecuada. La lógica de protección la cierra cuando las condiciones de presión no son válidas.","taughtIn":["air-2-c4"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1wt4s7z"}},{"id":"air-2-t4","type":"mcq","question":"Si falla la regulación primaria de presión neumática y la presión se eleva excesivamente, ¿qué componente proporciona una protección adicional?","options":["La overpressure valve, que cierra para limitar la sobrepresión","La RAM AIR inlet, que abre para descargar bleed al mixing unit","El trim-air valve de cockpit, que absorbe el exceso de presión","PTU, que convierte la presión neumática excedente en energía hidráulica"],"correct":0,"explanation":"La red de bleed incorpora una protección independiente frente a sobrepresión. Si la regulación normal no contiene la presión, la overpressure valve puede aislar la fuente.","taughtIn":["air-2-c2"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1eljwpn"}},{"id":"air-2-t5","type":"mcq","question":"WITH THE LOSS OF PNEUMATIC SYSTEM PRESSURE, THE ENGINE BLEED VALVE WILL:","options":["REMAIN IN IT'S CURRENT POSITION.","ASSUME THE CLOSED POSITION.","ASSUME THE OPEN POSITION.","ASSUME THE MID POSITION."],"correct":1,"explanation":"Ante la pérdida de presión del sistema neumático, la válvula de bleed de motor asume la posición cerrada, la misma lógica fail-safe aplicada a las válvulas de pack.","taughtIn":["air-2-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:a6n7g5"}},{"id":"air-2-t6","type":"mcq","question":"IF A BMC FAILS:","options":["THE REMAINING BMC WILL AUTOMATICALLY ASSUME MOST OF THE FAILED BMC´S FUNCTIONS.","ALL SYSTEM ASOCIATED WITH THE FAILED BMC ALSO FAIL.","THE ASSOCIATED BLEED VALVES CLOSE.","NONE OF THE ABOVE."],"correct":0,"explanation":"Ante la falla de un BMC, el BMC restante asume automáticamente la mayoría de las funciones del que falló, sin que fallen todos los sistemas asociados ni se cierren automáticamente las válvulas de bleed.","taughtIn":["air-2-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:k8rpvw"}}]},
{"id":"air-3","subject":"aire","order":3,"kind":"lesson","level":1,"ident":"XBL","title":"APU bleed and crossbleed","goal":"Explicar qué pasa al poner el APU BLEED en ON, cómo funciona el crossbleed en AUTO y qué válvulas maneja la tripulación.","intro":"En tierra, el APU suele dar el aire. Veamos qué abre y qué cierra solo cuando lo eliges.","minutes":6,"cards":[{"id":"air-3-c1","title":"APU BLEED ON","body":"El aire del APU está disponible en tierra y en vuelo. Con el botón **APU BLEED** en ON, la APU bleed valve abre si el APU gira a más del **95 %** y no hay fuga en el APU ni en el lado izquierdo. Entonces, en forma automática:\n- se abre la **crossbleed valve** (con el selector en AUTO);\n- se cierran las **bleed valves de los motores**.\n\nEs decir, el APU bleed tiene **prioridad** sobre el bleed de los motores, y alimenta los dos lados.","diagram":{"alt":"Con APU BLEED en ON: la APU bleed valve y la crossbleed valve abiertas, las bleed valves de los dos motores cerradas, y el aire del APU llega a los dos lados; una check valve protege al APU.","src":"assets/estaciones/diagramas/air-xbleed.svg"},"keyIdea":"APU BLEED ON: abre el crossbleed, cierra los bleeds de motor y alimenta los dos lados."},{"id":"air-3-c2","title":"The check valve","body":"Cerca del crossbleed duct, una **check valve** protege al APU cuando el aire viene de otra fuente: impide que el flujo vuelva hacia el APU.\n\nNo se usa al mismo tiempo el APU BLEED y una unidad de arranque de tierra de alta presión (HP air start unit), para no dañar el sistema de bleed.","keyIdea":"Una check valve impide que el aire vuelva al APU."},{"id":"air-3-c3","title":"X BLEED selector","body":"El selector **X BLEED** comanda la crossbleed valve con dos motores eléctricos, uno para AUTO y otro para el manual:\n- **AUTO:** abierta si la APU bleed valve está abierta; cerrada si está cerrada, o si hay una fuga en un ala, en un pylon o en el APU (salvo durante el arranque de un motor);\n- **OPEN** y **SHUT:** abierta o cerrada a mano.\n\nCon el APU BLEED en ON y el X BLEED en SHUT, la bleed valve del motor 2 sigue abierta.","keyIdea":"AUTO abre el crossbleed con el APU bleed y lo cierra ante una fuga."},{"id":"air-3-c4","title":"What the crew controls","body":"En el panel AIR COND, la tripulación comanda directamente tres cosas del sistema neumático:\n- las **bleed valves de los motores** (ENG 1 y ENG 2 BLEED);\n- la **APU bleed valve** (APU BLEED);\n- la **crossbleed valve** (X BLEED).\n\nLa HP valve no tiene botón: se maneja sola y se cierra con la bleed valve.","keyIdea":"Botones para ENG BLEED, APU BLEED y X BLEED; la HP valve es automática."}],"test":[{"id":"air-3-t1","type":"mcq","question":"APU BLEED AIR, WHEN SELECTED.","options":["HAS PRIORITY OVER ENGINE BLEED AIR.","WILL SUPPLY BLEED AIR ONLY IF THE ENG BLEED PB´S ARE SELECTED OFF.","WILL SUPPLY AIR ONLY IF THE X BLEED SELECTOR IS SELECTED OPEN.","DOES NOT HAVE PRIORITY OVER ENGINE BLEED AIR."],"correct":0,"explanation":"Con el APU BLEED en ON, se cierran solas las bleed valves de los motores y se abre el crossbleed: el aire del APU tiene prioridad y alimenta los dos lados.","taughtIn":["air-3-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:17191se"}},{"id":"air-3-t2","type":"mcq","question":"WITH APU BLEED ON AND ENGINE BLEED SWITCHES ON WITH ENGINES RUNNING. WHAT IS THE POSITION OF THE ENGINE BLEED VALVES?","options":["CLOSED.","OPEN.","DEPENDS ON THE CROSSBLEED SELECTOR."],"correct":0,"explanation":"Con el bleed del APU activo (que tiene prioridad), las válvulas de bleed de motor permanecen cerradas aunque sus switches estén en ON y los motores en marcha.","taughtIn":["air-3-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1n93710"}},{"id":"air-3-t3","type":"mcq","question":"WITH THE APU RUNNING, THE APU BLEED PUSH BUTTON SELECTED ON AND THE X BLEED SELECTOR TO AUTO, THE APU WILL:","options":["ONLY SUPPLY BLEED AIT TO LEFT SIDE.","SUPPLY PENEUMATIC AIR TO BOTH SIDES OF THE AIRCRAFT BECAUSE THE PNEUMATIC CROSSBLED VALVE AUTOMATICALLY OPENS.","WILL SUPPLY BLEED AIR ONLY TO THE LEFT SIDE UNLESS THE X BLEED SELECTOR IS SELECTED OPEN.","ONLY SUPPLY BLEED AIR TO THE RIGHT SIDE."],"correct":1,"explanation":"Con el APU funcionando, su bleed seleccionado ON, y el selector de crossbleed en AUTO, el APU suministra aire neumático a ambos lados del avión porque la válvula de crossbleed abre automáticamente en esa condición.","taughtIn":["air-3-c1","air-3-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1d65phu"}},{"id":"air-3-t4","type":"mcq","question":"THE AUTO POSITION OF THE X BLEED SELECTOR OPENS THE CROSSBLEED IF:","options":["AN ENGINE BLEED VALVE IS OPEN.","THE APU BLEED VALVE IS OPEN.","WHEN ENGINE START IS SELECTED."],"correct":1,"explanation":"En posición AUTO, el crossbleed se abre automáticamente cuando la válvula de bleed del APU está abierta, permitiendo distribuir el aire del APU hacia ambos lados del avión.","taughtIn":["air-3-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:359pia"}},{"id":"air-3-t5","type":"mcq","question":"¿Qué protección evita que el flujo neumático regrese hacia el APU?","options":["Una check valve en APU bleed","La outflow valve de presurización","La hot-air pressure-regulating valve","La Green hydraulic fire shutoff valve"],"correct":0,"explanation":"La red puede recibir aire desde varias fuentes. Una check valve en la línea del APU impide reverse flow hacia la unidad cuando otras fuentes presurizan el manifold.","taughtIn":["air-3-c2"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1iuxvkw"}},{"id":"air-3-t6","type":"mcq","question":"THE CREW MAY DIRECTLY CONTROL THE FOLLOWING BLEED VALVES:","options":["ENGINE, ENGINE HIGH PRESSURE, APU.","ENGINE, INTERMEDIATE PRESSURE, APU.","ENGINE, APU, CROSSBLEED."],"correct":2,"explanation":"La tripulación controla directamente las válvulas de bleed de motor, del APU, y la de crossbleed; las válvulas internas de alta/intermedia presión se gestionan automáticamente.","taughtIn":["air-3-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1psapi"}}]},
{"id":"air-4","subject":"aire","order":4,"kind":"lesson","level":1,"ident":"PCK","title":"Packs","goal":"Explicar cómo enfría el aire un pack, qué hace la pack flow control valve y cuándo se cierra sola.","intro":"El bleed llega caliente. Los packs lo enfrían con un ciclo de aire, sin refrigerante.","minutes":5,"cards":[{"id":"air-4-c1","title":"How a pack cools","body":"Los dos packs funcionan solos y en forma independiente. En cada uno:\n- el bleed entra por la pack flow control valve y se enfría en el **primary heat exchanger**;\n- el **compresor** de la air cycle machine lo comprime (sube presión y temperatura);\n- se enfría de nuevo en el **main heat exchanger**;\n- se expande en la **turbina**, y al expandirse pierde energía y queda **muy frío**. Esa misma turbina mueve el compresor y el ventilador.\n\nUn water separator seca el aire antes de la turbina.","diagram":{"alt":"Un pack: el bleed caliente pasa por la pack flow control valve, el primary heat exchanger, el compresor, el main heat exchanger y la turbina, que lo deja muy frío; los heat exchangers se enfrían con aire de impacto (ram air); una bypass valve mezcla aire caliente para regular la temperatura.","src":"assets/estaciones/diagramas/air-pack.svg"},"keyIdea":"Heat exchanger, compresor, heat exchanger y turbina: al expandirse, el aire sale muy frío."},{"id":"air-4-c2","title":"Pack flow control valve","body":"Cada pack tiene su **pack flow control valve**: es de **accionamiento neumático y control eléctrico**, y regula el caudal según su controlador. Sin presión de aire, un resorte la mantiene **cerrada**.\n\nSe cierra sola:\n- con sobretemperatura del pack (solo en tierra);\n- durante el **arranque de un motor**;\n- al presionar el ENG FIRE pb de ese lado, o con DITCHING.","keyIdea":"Neumática con control eléctrico; cerrada sin aire; se cierra en el arranque, con fuego o con ditching."},{"id":"air-4-c3","title":"During engine start","body":"En el arranque, la pack flow control valve del lado del motor que arranca se cierra al poner el ENG MODE en IGN (si la crossbleed está cerrada), y sigue cerrada mientras el motor arranca. Si la crossbleed está abierta, se cierran **las dos**.\n\nEn tierra, la reapertura se demora (30 o 60 segundos, según el avión) para no repetir el cierre al arrancar el segundo motor.","keyIdea":"En el arranque se cierran solas; con la crossbleed abierta, las dos."},{"id":"air-4-c4","title":"Ram air inlet flaps","body":"Los heat exchangers se enfrían con aire de impacto que entra por una **ram air inlet flap**. El controlador regula la temperatura del pack con esa flap y con una **bypass valve**.\n\nLa flap se **cierra en el despegue y en el aterrizaje** para no tragar objetos extraños: en el despegue, con potencia de despegue y el tren comprimido; en el aterrizaje, con el tren comprimido sobre 70 kt, y se abre 20 segundos después de bajar de 70 kt.\n\nNo se usan al mismo tiempo los packs y una unidad de aire acondicionado de tierra (LP).","keyIdea":"La ram air inlet flap enfría los heat exchangers y se cierra en despegue y aterrizaje."}],"test":[{"id":"air-4-t1","type":"mcq","question":"PACK FLOW CONTROL VALVE:","options":["IS PNEUMATICALLY OPERATED AND ELECTRICALLY CONTROLLED.","ELECTRICALLY OPERATED AND PNEUMATICALLY CONTROLLED.","OPENS AUTOMATICALLY DURING ENGINE STARTING.","IS SPRING LOADED TO OPEN."],"correct":0,"explanation":"La válvula de control de flujo de pack es de actuación neumática y control eléctrico, el mismo patrón de diseño usado en otras válvulas del sistema neumático del A320.","taughtIn":["air-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:7i6bmj"}},{"id":"air-4-t2","type":"mcq","question":"WHAT HAPPENS TO THE PACK FLOW CONTROL VALVES DURING ENGINE START?","options":["THEY MUST BE SELECTED OFF.","THEY MUST BE SELECTED OFF ON COLD DAYS ONLY.","THEY MUST BE SELECTED OFF ON HOT DAYS ONLY.","THEY AUTOMATICALLY CLOSE."],"correct":3,"explanation":"Se cierran solas durante el arranque: la del lado del motor que arranca o, con la crossbleed abierta, las dos. La tripulación no tiene que apagarlas.","taughtIn":["air-4-c2","air-4-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:146xint"}},{"id":"air-4-t3","type":"mcq","question":"WHAT POSITION DO THE PACK VALVES GO TO IN THE EVENT OF A LOSS OF THE BLEED SYSTEM PRESSURE?","options":["THEY REMAIN IN THEIR LAST POSITION.","FULL OPEN.","MID POSITION.","CLOSED."],"correct":3,"explanation":"Ante la pérdida de presión del sistema de bleed, las válvulas de pack se cierran, una respuesta de protección fail-safe consistente con la lógica del resto del sistema neumático.","taughtIn":["air-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1mme2tl"}},{"id":"air-4-t4","type":"mcq","question":"IT IS PERMISSIBLE TO USE SIMULTANEOUSLY PACKS AND LP GROUND UNIT DURING LONG STOPS IN A HOT AIRFIELD.","options":["YES.","NO."],"correct":1,"explanation":"No: no está permitido usar simultáneamente los packs del avión y una unidad de aire de baja presión en tierra durante escalas largas en un aeródromo caluroso.","taughtIn":["air-4-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1d3weiw"}}]},
{"id":"air-5","subject":"aire","order":5,"kind":"lesson","level":2,"ident":"FLW","title":"Pack flow","goal":"Explicar el selector PACK FLOW, cuándo el sistema da más caudal por su cuenta y cómo pide más aire a los motores o al APU.","intro":"Más caudal enfría o ventila más, pero cuesta bleed. Veamos quién decide cuánto aire entra.","minutes":5,"cards":[{"id":"air-5-c1","title":"PACK FLOW selector","body":"Con el selector **PACK FLOW** la tripulación ajusta el caudal según la cantidad de pasajeros y las condiciones:\n- **LO:** 80 % del caudal normal;\n- **NORM:** 100 %;\n- **HI:** 120 %, por ejemplo para sacar humo o en condiciones calurosas o húmedas.\n\nSi está en LO y no se alcanza a enfriar, el sistema sube el caudal hasta el 100 % por su cuenta.","diagram":{"alt":"Tabla del selector PACK FLOW: LO 80 %, NORM 100 % y HI 120 % del caudal normal; con un solo pack o con APU bleed, el sistema da HI aunque el selector diga otra cosa; en LO, si no alcanza a enfriar, sube hasta 100 %.","src":"assets/estaciones/diagramas/air-flujo.svg"},"keyIdea":"LO 80 %, NORM 100 %, HI 120 %; en LO puede subir solo hasta 100 %."},{"id":"air-5-c2","title":"When the system chooses HI","body":"Elija lo que elija la tripulación, el sistema da el caudal alto (**HI**) en dos casos:\n- con **un solo pack** funcionando;\n- cuando el **APU** da el bleed.\n\nEn esos casos, la posición del selector no cambia nada.","keyIdea":"Un solo pack o APU bleed: HI automático."},{"id":"air-5-c3","title":"Asking for more air","body":"Si una zona no alcanza su temperatura:\n- **con bleed de los motores:** si la presión del bleed es muy baja, el controlador pide a los dos **EIU** (Engine Interface Units) que suban la **minimum idle**, y así sube la presión del bleed. El motor acelera solo; el piloto no tiene que tocar la potencia;\n- **con APU bleed:** el controlador le pide más caudal al **ECB** (Electronic Control Box) del APU.","keyIdea":"Falta aire: los EIU suben la minimum idle; con el APU, se le pide al ECB."}],"test":[{"id":"air-5-t1","type":"mcq","question":"WHEN THE PACK FLOW CONTROL KNOB IS POSITIONED TO HI, AIR FLOW IS:","options":["80% OF NORMAL RATE.","100% OF NORMAL RATE.","120% OF NORMAL RATE.","150% OF NORMAL RATE."],"correct":2,"explanation":"En posición HI, el flujo de aire del pack corresponde al 120% de la tasa normal.","taughtIn":["air-5-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:12u3tw0"}},{"id":"air-5-t2","type":"mcq","question":"WHEN WOULD YOU SELECT PACK FLOW TO HI?","options":["SMOKE REMOVAL OR HOT/HUMID CONDITIONS.","WHEN PASSENGERS ARE COMPLAINING IT IS TOO COLD.","ABOVE FL 350.","ABOVE FL 250."],"correct":0,"explanation":"Conviene seleccionar HI para remoción de humo o en condiciones calurosas/húmedas, no simplemente porque los pasajeros se quejen de frío ni por criterios de altitud de vuelo.","taughtIn":["air-5-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:18uox9t"}},{"id":"air-5-t3","type":"mcq","question":"Si el PACK FLOW está en LO pero la demanda de enfriamiento no puede satisfacerse, ¿qué puede hacer automáticamente el sistema?","options":["Cerrar el pack afectado","Aumentar el pack flow hasta 100 %","Abrir RAM AIR aunque la cabina esté presurizada","Reducir el flujo a 60 %"],"correct":1,"explanation":"LO es una reducción para ahorrar bleed, no un límite fijo: si no se alcanza a enfriar, el sistema puede subir el caudal hasta el 100 %.","taughtIn":["air-5-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:vtv0ud"}},{"id":"air-5-t4","type":"mcq","question":"IF BLEED AIR IS BEING SUPPLIED BY THE APU OR IF ONE PACK FAILS, PACK FLOW WILL GO TO WHAT RATE?","options":["LOW.","MEDIUM.","HIGH."],"correct":2,"explanation":"Con bleed del APU en uso o ante la falla de un pack, el flujo del/de los pack(s) restante(s) pasa automáticamente a HIGH.","taughtIn":["air-5-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:wxemao"}},{"id":"air-5-t5","type":"mcq","question":"IN FLIGHT IF THE AIR PRESSURE IS INSUFFICIENT EVEN WITH THE HP VALVE OPEN:","options":["THE ENGINE SPOOLS UP AUTOMATICALLY. Spools up: incremento en thrust","ENGINE POWER HAS TO BE INCREASED BY THE PILOT.","PUSH THE HIGH PRESSURE P/B ON THE OVERHEAD PANEL."],"correct":0,"explanation":"Si una zona no alcanza su temperatura y la presión del bleed es muy baja, el controlador pide a los EIU que suban la minimum idle: el motor acelera solo y sube la presión del bleed, sin que el piloto toque la potencia.","taughtIn":["air-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1x43tah"}},{"id":"air-5-t6","type":"mcq","question":"WHEN APU IS SUPPLYING THE PACKS, THE PACK CONTROLLER SENDS A DEMAND SIGNAL TO INCREASE AIRFLOW WHEN A ZONE TEMPERATURE CANNOT BE SATISFIED. THIS SIGNAL IS SENT TO THE:","options":["PACK RAM AIR INLET FLAP.","APU ECB.","PACK OUTFLOW CONTROL VALVE."],"correct":1,"explanation":"Cuando el APU alimenta los packs, la señal de demanda de mayor flujo se dirige al ECB del APU, no a la compuerta de ram air del pack ni directamente a la válvula de control de outflow.","taughtIn":["air-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:jizo18"}}]},
{"id":"air-6","subject":"aire","order":6,"kind":"lesson","level":2,"ident":"TMP","title":"Temperature control","goal":"Explicar quién regula la temperatura de las tres zonas, cómo lo hacen los packs y para qué sirven las trim air valves.","intro":"Los dos packs mandan el mismo aire frío a todo el avión. ¿Cómo logra cada zona su propia temperatura?","minutes":5,"cards":[{"id":"air-6-c1","title":"Who controls the temperature","body":"Según el MSN:\n- **MSN más antiguos (hasta el 02321):** un **zone controller** y dos **pack controllers**;\n- **MSN más nuevos (desde el 02572):** dos **ACSC** (Air Conditioning System Controllers). El ACSC 1 regula el cockpit y el ACSC 2, la cabina. Cada ACSC tiene **dos lanes**: si falla la que manda, la otra toma el control completo.\n\nCada selector va de 18 °C (COLD) a 30 °C (HOT), con 24 °C a las 12 en punto.","keyIdea":"Hasta el MSN 02321, zone controller y pack controllers; desde el 02572, dos ACSC de dos lanes."},{"id":"air-6-c2","title":"Packs set the coldest","body":"El controlador compara la temperatura elegida en cada zona con la real (sensores en el cockpit y, para la cabina, en la extracción de lavatorios y galleys). Los **dos packs** entregan el aire para la zona que pide la temperatura **más baja**.\n\nLas otras zonas quedan más frías de lo que piden: ahí entran las trim air valves.","diagram":{"alt":"Los dos packs mandan aire frío a la mixing unit, con aire recirculado; de ahí sale un ducto a cada zona: cockpit, FWD CABIN y AFT CABIN. Antes de los packs se toma aire caliente por la hot air pressure regulating valve, y una trim air valve por zona agrega ese aire caliente a su ducto.","src":"assets/estaciones/diagramas/air-zonas.svg"},"keyIdea":"Los packs enfrían para la zona más fría; las demás se ajustan con aire caliente."},{"id":"air-6-c3","title":"Trim air valves","body":"Hay **tres trim air valves**, una por zona. Cada una **agrega aire caliente** al aire que sale de la mixing unit hacia su zona, y así afina su temperatura. Las comanda el controlador (en los MSN más nuevos, el ACSC 1 la del cockpit y el ACSC 2 las de la cabina).\n\nEse aire caliente se toma **antes de los packs**, y su presión la regula la **hot air pressure regulating valve**.","keyIdea":"Tres trim air valves, una por zona, agregan aire caliente tomado antes de los packs."}],"test":[{"id":"air-6-t1","type":"mcq","question":"HOW MANY TRIM AIR VALVES ARE THERE?","options":["ONE TRIM AIR VALVE.","THREE: ONE EACH FOR THE COCKPIT ZONE, THE FORWARD CABIN ZONE, AND THE AFT CABIN ZONE.","TWO: ONE FOR THE COCKPIT AND FIRST CLASS ZONE, AND ONE FOR THE CABIN ZONE.","FOUR: ONE EACH FOR THE COCKPIT ZONE, THE FIRST CLASS ZONE, AND TWO FOR THE AFT ZONE."],"correct":1,"explanation":"Hay tres válvulas de trim air, una para cada una de las tres zonas de temperatura del avión.","taughtIn":["air-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:15um4yy"}},{"id":"air-6-t2","type":"mcq","question":"TRIM AIR VALVE, EACH ONE OPTIMIZES THE TEMPERATURE BY:","options":["ADDING HOT AIR.","ADDING FRESH AIR.","MODULATION OF PACK FLOW.","ADDING RECIRCULATED AIR."],"correct":0,"explanation":"Cada válvula de trim air optimiza la temperatura de su zona agregando aire caliente al flujo, no agregando aire fresco, modulando el flujo del pack, ni agregando aire recirculado.","taughtIn":["air-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:10iw0p8"}},{"id":"air-6-t3","type":"mcq","question":"THE TEMPERATURE OF EACH AIRCRAFT ZONE IS OPTIMIZED BY MEANS OF?","options":["A HOT AIR PRESSURE REGULATING VALVE.","A ZONE CONTROL VALVE.","A TRIM AIR VALVE.","BOTH A AND B."],"correct":2,"explanation":"La temperatura de cada zona se optimiza mediante su respectiva válvula de trim air.","taughtIn":["air-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1yv9a1a"}},{"id":"air-6-t4","type":"mcq","question":"¿Cuál es la función de los trim air valves en la regulación de temperatura?","options":["Añaden hot air al aire de la mixing unit","Regulan la presión mediante el outflow","Cierran los packs durante el arranque","Recirculan cabin air hacia los packs"],"correct":0,"explanation":"Los packs producen el aire acondicionado base. Para ajustar cada zona a su temperatura objetivo, los trim air valves añaden una cantidad modulada de aire caliente al flujo que sale de la mixing unit; por eso son un elemento de ajuste fino de temperatura, no de presurización.","taughtIn":["air-6-c3"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:115t4fh"}},{"id":"air-6-t5","type":"mcq","question":"HOT AIR PRESSURE REGULATING VALVE:","options":["REGULATES THE PRESSURE OF HOT AIR TAPPED UPSTREAM OF THE PACKS.","IS SPRING LOADED OPEN IN THE ABSENCE OF AIR.","OPENS AUTOMATICALLY IN CASE OF DUCT OVERHEAT.","OPENS AUTOMATICALLY IF THE CABIN TRIM AIR VALVE FAILS."],"correct":0,"explanation":"Esta válvula regula la presión del aire caliente tomado aguas arriba de los packs, el aire que luego alimenta el sistema de trim air para el ajuste fino de temperatura por zona.","taughtIn":["air-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1lc8753"}}]},
{"id":"air-7","subject":"aire","order":7,"kind":"lesson","level":2,"ident":"TRM","title":"Hot air and failures","goal":"Explicar el botón HOT AIR, su luz FAULT, y qué se pierde con fallas de la hot air valve, de una trim air valve, de un ACSC o de la air cycle machine.","intro":"El aire caliente es el ajuste fino. Veamos qué lo protege y qué queda cuando algo falla.","minutes":6,"cards":[{"id":"air-7-c1","title":"HOT AIR pb","body":"- **ON:** la hot air pressure regulating valve regula la presión del aire caliente.\n- **OFF:** se cierran la hot air valve **y las trim air valves**.\n- **FAULT:** luz ámbar, con alerta del ECAM, cuando hay sobretemperatura en un ducto (**duct overheat**): la temperatura del ducto llega a **88 °C**. La hot air valve y las trim air valves se cierran solas. La luz se apaga cuando la temperatura baja de 70 °C y la tripulación pone el botón en OFF.","keyIdea":"HOT AIR OFF cierra hot air y trim air; FAULT a 88 °C, y se resetea bajo 70 °C."},{"id":"air-7-c2","title":"Valve failures","body":"- **Hot air valve falla abierta:** sin efecto.\n- **Hot air valve falla cerrada:** se pierde la regulación optimizada; las trim air valves se cierran; el pack 1 regula el cockpit a lo elegido y el pack 2 la cabina, al promedio de las dos zonas.\n- **Una trim air valve falla:** se pierde la regulación optimizada de esa zona.","keyIdea":"Hot air abierta: nada; cerrada: pack 1 para el cockpit y pack 2 para la cabina."},{"id":"air-7-c3","title":"ACSC failures","body":"En los MSN más nuevos (desde el 02572):\n- **falla una lane** de un ACSC: sin efecto, la otra toma el control;\n- **fallan las dos lanes**: se pierde ese pack y se cierra la hot air valve; sus trim air valves quedan en la posición que tenían.","keyIdea":"Una lane: nada. Las dos: se pierde el pack y se cierra la hot air valve."},{"id":"air-7-c4","title":"Air cycle machine failure","body":"Si la air cycle machine se traba (compressor o turbine seizure), el pack puede seguir en **heat exchanger cooling mode**: la mayor parte del aire enfriado en el primary heat exchanger pasa directo por la bypass valve, y el resto por la máquina trabada.\n\nEl **caudal del pack baja**, pero el controlador sigue regulando la temperatura con la bypass valve y la ram air inlet flap.","keyIdea":"Air cycle machine trabada: el pack sigue con los heat exchangers, con menos caudal."}],"test":[{"id":"air-7-t1","type":"mcq","question":"¿Qué hace el sistema al seleccionar HOT AIR OFF?","options":["Abre hot air valve y trim air valves","Cierra hot air valve y trim air valves","Cierra los packs, deja trim air abiertos","Inhibe el ECAM sin cambiar las valves"],"correct":1,"explanation":"Con HOT AIR OFF se cierra la hot air pressure regulating valve y también los trim air valves. La selección aísla el circuito de trim air caliente.","taughtIn":["air-7-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1n1ono5"}},{"id":"air-7-t2","type":"mcq","question":"¿A qué temperatura se detecta un HOT AIR duct overheat?","options":["70 °C","80 °C","88 °C","100 °C"],"correct":2,"explanation":"El circuito de falla del HOT AIR detecta un duct overheat cuando la temperatura del ducto llega a 88 °C (190 °F).","taughtIn":["air-7-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:wus4k3"}},{"id":"air-7-t3","type":"mcq","question":"HOT AIR PRESS. REG. VALVE FAILED OPEN.","options":["OPTIMIZED REGULATION IS LOST.","THE TEMPERATURE STAYS AT THE VALUE SELECTED.","NO EFFECT.","CABIN TEMPERATURE WILL BE CONTROLLED AT THE UPPER LIMIT 30 DEG. C."],"correct":2,"explanation":"Si la hot air pressure regulating valve falla abierta, no hay efecto. El problema es si falla cerrada: se pierde la regulación optimizada y las trim air valves se cierran.","taughtIn":["air-7-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1vsygoa"}},{"id":"air-7-t4","type":"mcq","question":"Si fallan ambas lanes del Air Conditioning System Controller de un pack, ¿qué ocurre con ese pack?","options":["Se pierde el pack afectado y cierra la hot-air pressure-regulating valve","El pack continúa sin limitaciones porque el otro pack controller asume ambos lados","Solo se pierde la indicación ECAM, pero la regulación permanece completamente normal","El pack pasa automáticamente a RAM AIR con outflow valve a 50 %"],"correct":0,"explanation":"Una lane puede respaldar a la otra, pero la pérdida de ambas elimina el control del pack asociado. La protección también cierra la válvula de hot air correspondiente.","taughtIn":["air-7-c3"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:103y305"}},{"id":"air-7-t5","type":"mcq","question":"Con una sola lane del Air Conditioning System Controller fallada, ¿qué efecto operacional tiene?","options":["Ningún efecto: la segunda lane toma el control","Pérdida inmediata del pack y de todos los trim air valves","El pack queda fijo a HIGH flow hasta aterrizar","La presurización pasa automáticamente a manual mode"],"correct":0,"explanation":"Los controladores están diseñados con redundancia interna. Una lane puede asumir la función de la otra, por lo que una falla simple no implica pérdida del pack.","taughtIn":["air-7-c3"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:12a3trr"}},{"id":"air-7-t6","type":"mcq","question":"Si falla mecánicamente el Air Cycle Machine de un pack, ¿queda necesariamente perdido el pack completo?","options":["No; puede operar en heat-exchanger cooling mode con flujo reducido","Sí; el pack valve cierra y no existe ninguna vía alternativa de cooling","No; el otro ACM impulsa mecánicamente al ACM fallado mediante el crossbleed","Sí; ambos packs se desconectan automáticamente para mantener simetría"],"correct":0,"explanation":"No: el pack puede seguir en heat exchanger cooling mode. La mayor parte del aire pasa por la bypass valve después del primary heat exchanger; el caudal baja, pero el pack sigue entregando aire.","taughtIn":["air-7-c4"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:fdv9t8"}}]},
{"id":"air-8","subject":"aire","order":8,"kind":"lesson","level":2,"ident":"RAM","title":"Emergency ram air","goal":"Explicar para qué sirve el emergency ram air, cuándo entra aire de verdad y qué hace la outflow valve.","intro":"Si los dos packs se pierden o hay que sacar humo, queda una entrada de aire exterior. Pero solo sirve sin presión en la cabina.","minutes":6,"cards":[{"id":"air-8-c1","title":"What it is for","body":"Una entrada de **emergency ram air** ventila el cockpit y la cabina para **sacar humo** o si fallan **los dos packs**. El aire exterior llega directo a la **mixing unit**.\n\nSe abre con el botón **RAM AIR** (con guarda) del panel AIR COND, siempre que no esté seleccionado DITCHING. No se abre solo: es una acción de la tripulación. El memo verde **RAM AIR ON** lo recuerda.","diagram":{"alt":"El emergency ram air: la entrada de aire exterior lleva aire a la mixing unit; abajo, dos casos: con ΔP menor que 1 PSI entra aire y la outflow valve abre cerca del 50 % en automático; con ΔP de 1 PSI o más, la check valve no abre y no entra aire.","src":"assets/estaciones/diagramas/air-ramair.svg"},"keyIdea":"Ram air: para humo o los dos packs perdidos; lo abre la tripulación; llega a la mixing unit."},{"id":"air-8-c2","title":"Only below 1 PSI","body":"Con el RAM AIR en ON:\n- **ΔP menor que 1 PSI:** entra aire, y la **outflow valve abre cerca del 50 %** si está en control automático (en manual no abre sola);\n- **ΔP de 1 PSI o más:** la check valve después de la puerta del ram air no abre y **no entra aire**, aunque la puerta esté abierta; la outflow valve sigue con su control normal.\n\nPor eso el ram air solo se usa con la diferencia de presión bajo 1 PSI.","keyIdea":"Bajo 1 PSI entra aire y la outflow valve abre cerca del 50 %; sobre 1 PSI no entra nada."},{"id":"air-8-c3","title":"Both packs lost","body":"Con **AIR PACK 1+2 FAULT**, el procedimiento:\n- PACK 1 y PACK 2 en **OFF**;\n- **descender a FL 100** o a la MEA-MORA, la que sea más alta;\n- cuando el ΔP baja de 1 PSI y el avión está bajo FL 100: **RAM AIR ON**.\n\nEl nivel máximo queda en FL 100 o la MEA-MORA.","keyIdea":"Packs OFF, descenso a FL 100 o MEA-MORA y RAM AIR ON con ΔP bajo 1 PSI."}],"test":[{"id":"air-8-t1","type":"mcq","question":"WHAT IS THE FUNCTION OF THE RAM AIR VALVE?","options":["VENTILATION WHILE ON THE GROUND.","EMERGENCY SMOKE REMOVAL AND VENTILATION IN THE EVENT LF DUAL PACK FAILURE.","AVIONICS COOLING.","CARGO VENTILATION & AVIONICS COOLING."],"correct":1,"explanation":"La función principal de la válvula de ram air es la remoción de humo de emergencia y la ventilación ante una falla de ambos packs, no la ventilación general en tierra ni el enfriamiento de aviónica.","taughtIn":["air-8-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1t9zwbx"}},{"id":"air-8-t2","type":"mcq","question":"WHEN WOULD YOU SELECT RAM AIR ON?","options":["IF ADDITIONAL COOLING IS REQUIRED ON THE GROUND.","DUAL PACKS FAILURE OR SMOKE REMOVAL.","WHEN PACK TEMPERATURES ARE TOO HIGH.","WHEN THERE IS SMOKE IN THE CABIN."],"correct":1,"explanation":"Se selecciona ram air ON ante una falla de ambos packs o para remoción de humo, no simplemente para enfriamiento adicional en tierra ni cuando la temperatura de los packs es alta.","taughtIn":["air-8-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:ezvbut"}},{"id":"air-8-t3","type":"mcq","question":"Si se necesita ventilación de emergencia, ¿a dónde puede llevar aire exterior el RAM AIR inlet?","options":["Al hot air manifold","A la mixing unit","A los reservorios","Solo al avionics bay"],"correct":1,"explanation":"El RAM AIR constituye una vía alternativa de ventilación cuando la alimentación normal mediante packs no está disponible. El aire exterior entra a la mixing unit y desde allí puede distribuirse al cockpit y la cabina.","taughtIn":["air-8-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:7oxw66"}},{"id":"air-8-t4","type":"mcq","question":"WHAT HAPPENS TO THE OUTFLOW VALVE WHEN THE RAM AIR SWITCH IS SELECTED ON?","options":["THE OUTFLOW VALVE OPENS IMMEDIATELY.","THE OUTFLOW VALVE OPENS IF CABIN DIFFERENTIAL PRESSURE IS LESS THAN 1 PSI.","NORMAL OUTFLOW VALVE CONTROL IS MAINTAINED."],"correct":1,"explanation":"Al seleccionar ram air ON, la válvula de outflow abre solo si la diferencial de presión de cabina es menor a 1 PSI, respetando la misma condición de seguridad que aplica al switch de ram air.","taughtIn":["air-8-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1fxi2ri"}},{"id":"air-8-t5","type":"mcq","question":"Con RAM AIR ON y Δp inferior a 1 PSI, bajo control automático, ¿qué hace el outflow valve?","options":["Cierra aproximadamente al 0 %","Abre aproximadamente al 50 %","Permanece en la última posición","Abre completamente al 100 %"],"correct":1,"explanation":"Para que el aire exterior pueda atravesar la aeronave necesita una vía de salida. Con Δp < 1 PSI, el sistema abre aproximadamente a mitad el outflow valve en AUTO y permite que el ram air llegue directamente a la mixing unit.","taughtIn":["air-8-c2"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:wq3frf"}},{"id":"air-8-t6","type":"mcq","question":"WHAT LIMITATION IS ASSOCIATED WITH THE RAM AIR VALVE?","options":["DO NOT OPEN IF CABIN PRESSURE IS GREATER THAN 1 PSI.","ONLY OPEN WHILE ON THE GROUND.","WILL NOT OPEN IF THE DITCHING SWITCH IS OFF.","OPERATION IS AUTOMATIC."],"correct":0,"explanation":"No debe abrirse la válvula de ram air si la presión de cabina es mayor a 1 PSI, la misma limitación de seguridad aplicable al switch correspondiente.","taughtIn":["air-8-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:eyv2p1"}}]},
{"id":"air-9","subject":"aire","order":9,"kind":"lesson","level":2,"ident":"PRS","title":"Pressurization system","goal":"Explicar las piezas de la presurización: los dos controladores, la outflow valve con sus tres motores y las safety valves.","intro":"La cabina se presuriza dejando salir menos aire del que entra. Una sola válvula hace el trabajo.","minutes":5,"cards":[{"id":"air-9-c1","title":"Two controllers","body":"Dos **Cabin Pressure Controllers** (CPC), iguales e independientes, controlan la presurización en forma automática. Reciben datos de los **ADIRS**, de los **FMGC**, de los **EIU** y de los **LGCIU**.\n\nSolo **uno trabaja a la vez**; el otro queda en espera. El cambio es **automático**: 70 segundos después de cada aterrizaje, o si falla el que está trabajando. La tripulación puede forzarlo: MODE SEL en MAN al menos 10 segundos y de vuelta a AUTO.","keyIdea":"Dos CPC, uno activo; alternan solos después de cada aterrizaje o si uno falla."},{"id":"air-9-c2","title":"Outflow valve: three motors","body":"Hay **una sola outflow valve**, atrás a la derecha, bajo la línea de flotación, con flaps que abren hacia adentro y hacia afuera. Su actuador tiene **tres motores eléctricos independientes**:\n- **dos automáticos**, uno de cada CPC;\n- **uno manual**, que funciona solo con el MODE SEL en MAN.\n\nCualquiera de los tres puede mover la válvula.","diagram":{"alt":"La cabina con la outflow valve atrás: su actuador tiene dos motores automáticos (uno del CPC 1 y otro del CPC 2) y un motor manual; dos safety valves en el mamparo trasero limitan la diferencia de presión a 8,6 PSI arriba y 1 PSI abajo.","src":"assets/estaciones/diagramas/air-presion.svg"},"keyIdea":"Una outflow valve con tres motores: dos automáticos y uno manual."},{"id":"air-9-c3","title":"Safety valves","body":"Dos **safety valves** independientes, en el mamparo de presión trasero, impiden que la presión de la cabina quede:\n- **muy alta:** más de **8,6 PSI** sobre la exterior;\n- **muy baja:** más de **1 PSI** bajo la exterior (diferencia negativa).\n\nSon **neumáticas**: funcionan sin electricidad.","keyIdea":"Dos safety valves neumáticas: límite de 8,6 PSI positivo y 1 PSI negativo."}],"test":[{"id":"air-9-t1","type":"mcq","question":"PRESSURIZATION CONTROLLERS RECEIVE INPUTS FROM:","options":["LGCIU, ADIRU, FMGS, AND EIU.","LGCIU/'S AND THE MCDU.","LGCIU/'S AND PITOT STATIC SOURCES.","MCDU AND LGCIU/'S."],"correct":0,"explanation":"Los controladores de presurización reciben datos de LGCIU (posición de tren), ADIRU (datos de aire), FMGS (plan de vuelo) y EIU, una combinación más amplia que solo LGCIU y MCDU.","taughtIn":["air-9-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:12wubxi"}},{"id":"air-9-t2","type":"mcq","question":"TRANSFER BETWEEN THE TWO CABIN PRESSURE CONTROLLERS IS:","options":["ACCOMPLISHED WITH A SWITCH OVERHEAD.","AUTOMATIC AFTER LANDING OR IN CASE THE OPERATING CONTROLLER FAILS.","AUTOMATICALLY AT EACH TAKEOFF."],"correct":1,"explanation":"La transferencia entre ambos controladores de presurización es automática, ya sea después del aterrizaje o ante la falla del controlador que esté operando, no mediante un switch manual dedicado ni en cada despegue.","taughtIn":["air-9-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1tcpfcs"}},{"id":"air-9-t3","type":"mcq","question":"HOW CAN YOU CHANGE PRESSURIZATION CONTROLLERS DURING FLIGHT?","options":["CYCLE THE LDG ELEV AUTO KNOB OUT OF THE AUTO POSITION THEN BACK TO AUTO.","CYCLE THE CABIN PRESS MODE SEL PUSHBUTTON TO THE MAN POSITION THEN BACK TO AUTO.","CYCLE THE CABIN PRESSURIZATION MAN V/S CTL SWITCH."],"correct":1,"explanation":"Para forzar el cambio de controlador de presurización en vuelo, se cicla el pushbutton CABIN PRESS MODE SEL a MAN y luego de vuelta a AUTO, no ciclando el selector de elevación de aterrizaje ni el switch manual de V/S.","taughtIn":["air-9-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:zg6qh"}},{"id":"air-9-t4","type":"mcq","question":"THE OUTFLOW VALVE IS POWERED BY:","options":["ONE OF TWO ELECTRIC MOTORS.","ONE OF THREE ELECTRIC MOTORS.","THREE MECHANICALLY LINKED ELECTRIC MOTORS."],"correct":1,"explanation":"La válvula de outflow está accionada por uno de tres motores eléctricos disponibles, dos de operación automática y uno manual de respaldo.","taughtIn":["air-9-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1rphtgt"}},{"id":"air-9-t5","type":"mcq","question":"THE PURPOSE OF THE SAFETY VALVE IS TO AVOID:","options":["EXCESSIVE POSITIVE PRESSURE DIFFERENTIAL.","EXCESSIVE NEGATIVE DIFFERENTIAL.","BOTH ARE CORRECT."],"correct":2,"explanation":"La válvula de seguridad protege tanto contra una diferencial de presión positiva excesiva como contra una diferencial negativa excesiva; ambas condiciones están cubiertas.","taughtIn":["air-9-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:ts8f7s"}},{"id":"air-9-t6","type":"mcq","question":"THE SAFETY VALVES ARE OPERATED:","options":["ELECTRICALLY.","HYDRAULICALLY.","PNEUMATICALLY."],"correct":2,"explanation":"Las válvulas de seguridad son de operación neumática, no eléctrica ni hidráulica.","taughtIn":["air-9-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:pqmyob"}}]},
{"id":"air-10","subject":"aire","order":10,"kind":"lesson","level":2,"ident":"SCH","title":"Pressurization schedule","goal":"Explicar cómo se presuriza la cabina en cada fase del vuelo y de dónde saca el sistema la elevación de aterrizaje.","intro":"La presurización automática sigue un programa de punta a punta del vuelo. Veamos cada fase.","minutes":6,"cards":[{"id":"air-10-c1","title":"On ground and takeoff","body":"- **En tierra (ground function):** la outflow valve está **totalmente abierta**: no queda presión en la cabina.\n- **Despegue:** para evitar un salto de presión en la rotación, el sistema **prepresuriza** la cabina **durante la carrera de despegue**, a 400 ft/min de cabina, hasta un ΔP de 0,1 PSI. Al despegar empieza el ascenso.","diagram":{"alt":"Perfil de la presurización a lo largo del vuelo: en tierra la outflow valve abierta; en el despegue, prepresurización hasta 0,1 PSI; en el ascenso la cabina sube según una ley fija; en crucero se mantiene, con un máximo de unos 8 000 ft; en el descenso baja hasta la presión del aeropuerto más 0,1 PSI; en tierra se libera y la outflow valve abre del todo.","src":"assets/estaciones/diagramas/air-perfil.svg"},"keyIdea":"En tierra, outflow valve abierta; en la carrera de despegue, prepresurización."},{"id":"air-10-c2","title":"Climb and cruise","body":"- **Ascenso:** la altitud de cabina sube según una ley fija, que tiene en cuenta la velocidad de ascenso del avión.\n- **Crucero:** la cabina se mantiene en la altitud de cabina alcanzada al nivelar, o en la elevación del aeropuerto de destino si es más alta, con un máximo de unos **8 000 ft**.\n\nEn tierra, en el ascenso y en el descenso, el sistema puede operar en aeropuertos altos de hasta 14 100 ft de presión.","keyIdea":"Ascenso por una ley fija; crucero con un máximo de unos 8 000 ft de cabina."},{"id":"air-10-c3","title":"Descent and landing","body":"- **Descenso:** la cabina baja de modo que, poco antes de aterrizar, quede a la presión del aeropuerto más 0,1 PSI; como máximo a 750 ft/min.\n- **Aterrizaje:** al tocar tierra, la presión que queda se libera a 500 ft/min de cabina, y **55 segundos** después la outflow valve abre del todo.\n\nSi el avión desciende poco después de despegar, el modo **ABORT** vuelve la cabina a la presión del aeropuerto de salida.","keyIdea":"Descenso hasta la presión del aeropuerto + 0,1 PSI; outflow valve abierta 55 s después de aterrizar."},{"id":"air-10-c4","title":"Landing elevation","body":"Normalmente, el controlador usa la **elevación de aterrizaje y el QNH del FMGS** (el plan de vuelo activo) y la altitud de los ADIRS.\n\nCon el selector **LDG ELEV** en AUTO, la elevación viene del FMGS. Fuera de AUTO, el sistema usa la elevación elegida con el selector, y aparece el memo verde **MAN LDG ELEV**. La elevación usada se lee en el ECAM, en la página CAB PRESS y en la CRUISE: la escala del selector es solo indicativa.","keyIdea":"LDG ELEV en AUTO: elevación y QNH del FMGS; fuera de AUTO, lo que se elige, leído en el ECAM."}],"test":[{"id":"air-10-t1","type":"mcq","question":"DURING GROUND FUNCTION OPERATION, THE OUTFLOW VALVE IS:","options":["FULLY OPEN.","FULLY CLOSED.","POSITIONED ACCORDING TO FMGS DEMANDS."],"correct":0,"explanation":"En tierra, la válvula de outflow permanece completamente abierta, ya que no hay necesidad de mantener presión diferencial hasta iniciar el despegue.","taughtIn":["air-10-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:10a8g2d"}},{"id":"air-10-t2","type":"mcq","question":"WHEN DOES NORMAL PRESSURIZATION OCCUR?","options":["AFTER SECOND ENGINE START.","PRESSURIZATION OCCURS DURING TAXI.","PRESSURIZATION OCCURS DURING THE TAKEOFF ROLL.","AFTER RATATION."],"correct":2,"explanation":"La presurización normal ocurre durante la carrera de despegue, coincidiendo con el cierre progresivo de la válvula de outflow que estaba abierta en tierra.","taughtIn":["air-10-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:et5wli"}},{"id":"air-10-t3","type":"mcq","question":"WHAT IS THE NORM. MAX. CABIN ALTITUDE?","options":["8,000 FT.","9,550 FT +/-350 FT.","14,000 FT.","800 FT."],"correct":0,"explanation":"La altitud máxima normal de cabina es 8,000 ft, el objetivo de diseño del sistema de presurización durante el crucero.","taughtIn":["air-10-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1xmbhzi"}},{"id":"air-10-t4","type":"mcq","question":"WHEN LANDING ELEVATION IS SET TO AUTO, THE LANDING ELEVATION IS SENT TO THE CONTROLLER FROM:","options":["FMGS.","FCU.","ADIRS."],"correct":0,"explanation":"En modo AUTO, la elevación de aterrizaje proviene del FMGS (basada en el plan de vuelo), no del FCU ni directamente del ADIRS.","taughtIn":["air-10-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:5fuh9o"}},{"id":"air-10-t5","type":"mcq","question":"BOTH PRESSURIZATION AUTO CONTROLLERS ARE SET BY THE ACTIVE FLIGHT PLAN LOADED IN THE MCDU. THE QNH ENTRY ON THE MCDU APPROACH PERFORMANCE PAGE REFINES THE DEPRESSURIZATION SCHEDULE FOR THE LANDING.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: los controladores de presurización usan el plan de vuelo activo, y el QNH ingresado en la página de performance de aproximación afina el programa de despresurización para el aterrizaje.","taughtIn":["air-10-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:q7zx2z"}},{"id":"air-10-t6","type":"mcq","question":"IF YOU SELECT A POSITION OTHER THAN THE AUTO DETENT ON THE LDG ELEV AUTO SELECTOR, HOW CAN YOU SEE TE ACTUAL LANDING ELEVATION VALUE?","options":["ON THE ECAM CRUISE.","ON THE PRESS PAGE.","ON THE ECAM CRUISE OR THE PRESS PAGE."],"correct":2,"explanation":"El valor de elevación de aterrizaje seleccionado manualmente puede verificarse tanto en la página ECAM CRUISE como en la página PRESS.","taughtIn":["air-10-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:qzyd4e"}}]},
{"id":"air-11","subject":"aire","order":11,"kind":"lesson","level":2,"ident":"AVN","title":"Avionics ventilation","goal":"Explicar cómo se enfría la aviónica, las configuraciones abierta y cerrada, y qué hacen los botones BLOWER y EXTRACT.","intro":"Los computadores también necesitan aire. Su ventilación es automática y cambia entre tierra y vuelo.","minutes":6,"cards":[{"id":"air-11-c1","title":"AEVC and two fans","body":"La ventilación de aviónica es automática. La maneja el **AEVC** (Avionics Equipment Ventilation Computer), que controla todos sus ventiladores y válvulas. **Dos ventiladores eléctricos**, el **blower** y el **extract**, hacen circular el aire siempre que el avión tenga energía.\n\nUn Fan Speed Controller les sube la velocidad cuando el aire pasa de **40 °C** y la baja cuando vuelve bajo **35 °C**.","keyIdea":"El AEVC maneja dos ventiladores (blower y extract); alta velocidad sobre 40 °C."},{"id":"air-11-c2","title":"Open or closed circuit","body":"- **Circuito abierto (open):** normalmente en tierra, con temperatura cálida. Las **skin air inlet y outlet valves** están abiertas: entra aire de afuera y el aire caliente de los equipos sale al exterior.\n- **Circuito cerrado (closed):** normalmente en vuelo. Esas válvulas se cierran y el aire circula en el avión, enfriándose en el **skin heat exchanger**, junto al revestimiento.\n- **Intermedio:** en vuelo, si el revestimiento está muy caliente, las válvulas quedan parcialmente abiertas.","diagram":{"alt":"Dos configuraciones de la ventilación de aviónica. Circuito abierto, en tierra con calor: el aire entra por la skin air inlet valve, pasa por los equipos y sale por la skin air outlet valve. Circuito cerrado, en vuelo: esas válvulas cerradas y el aire circula por el skin heat exchanger.","src":"assets/estaciones/diagramas/air-avionica.svg"},"keyIdea":"En tierra con calor, circuito abierto; en vuelo, cerrado con el skin heat exchanger."},{"id":"air-11-c3","title":"BLOWER and EXTRACT","body":"- **Un botón en OVRD:** el sistema pasa a circuito cerrado y **agrega aire del aire acondicionado** a la ventilación. Con BLOWER en OVRD, el blower se detiene.\n- **Los dos en OVRD** (configuración de humo): el aire acondicionado entra, pasa por la aviónica y **sale al exterior**; el blower se detiene y el extract sigue.\n\nSi se detecta humo en el aire de la aviónica, se encienden las luces FAULT de BLOWER y EXTRACT.","keyIdea":"OVRD agrega aire acondicionado; los dos en OVRD lo sacan al exterior (humo)."},{"id":"air-11-c4","title":"Lavatories and galleys","body":"Un **extraction fan** saca aire de la cabina por los lavatorios y galleys y lo descarga cerca de la outflow valve. Funciona **siempre que haya energía eléctrica**.\n\nEn tierra con mucho calor, el uso de la energía eléctrica del avión con la ventilación normal tiene límite de tiempo: sin límite hasta 49 °C, y desde ahí entre 2 horas y media hora según la temperatura exterior.","keyIdea":"El extraction fan de lavatorios y galleys funciona siempre que hay energía."}],"test":[{"id":"air-11-t1","type":"mcq","question":"¿Qué computador gobierna fans y valves del avionics ventilation system?","options":["AEVC","BMC","CPC","FLSCU"],"correct":0,"explanation":"El Avionics Equipment Ventilation Computer coordina los ventiladores y las diferentes valves que configuran el circuito de ventilación de equipos.","taughtIn":["air-11-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1ves6ik"}},{"id":"air-11-t2","type":"mcq","question":"¿Qué hace el Fan Speed Controller cuando la ventilation-air temperature supera aproximadamente 40 °C?","options":["Los avionics ventilation fans pasan a high speed","Los avionics ventilation fans se detienen para evitar overheat","Se selecciona automáticamente RAM AIR del sistema de cabina","El outflow valve se abre por completo para descargar la cabina"],"correct":0,"explanation":"El FSC adapta la velocidad del fan a la carga térmica. Por encima de 40 °C ordena high speed para aumentar la extracción/recirculación de calor.","taughtIn":["air-11-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:9dg8wt"}},{"id":"air-11-t3","type":"mcq","question":"DURING THE EXTERIOR PREFLIGHT ON A WARM DAY, IN WHAT POSITION WOULD YOU EXPECT TO FIND THE AVIONICS VENTILATION SYSTEM INLET AND EXTRACT VALVES TO BE IN?","options":["OPEN.","INTERMEDIATE.","CLOSED.","FIRE."],"correct":0,"explanation":"En tierra y con temperatura cálida, es esperable encontrar las válvulas de entrada y extracción del sistema de ventilación de aviónica abiertas, ya que en esa condición conviene el circuito abierto en vez del intercambiador de calor usado en vuelo.","taughtIn":["air-11-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:131mvl4"}},{"id":"air-11-t4","type":"mcq","question":"WHICH CONFIGURATION IS THE AVIONICS VENTILATION SYSTEM IN WHILE AIRBORNE WITH NO ABNORMALS PRESENT?","options":["OPEN.","SMOKE.","FIRE.","CLOSED."],"correct":3,"explanation":"En vuelo, sin condiciones anormales, el sistema de ventilación de aviónica opera en configuración cerrada (circuito cerrado con intercambiador de calor).","taughtIn":["air-11-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:10op4u3"}},{"id":"air-11-t5","type":"mcq","question":"WHEN EITHER THE BLOWER OR EXTRACT SWITCHES ARE IN OVRD, AIR FROM THE AIR CONDITIONING SYSTEM IS ADDED TO VENTILATION AIR.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: al usar el override de cualquiera de los dos ventiladores, se agrega aire del sistema de aire acondicionado al flujo de ventilación de aviónica.","taughtIn":["air-11-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:2ed5g5"}},{"id":"air-11-t6","type":"mcq","question":"THE LAVATORY/GALLEY EXTRACT FAN OPERATES:","options":["ONLY ON THE GROUND.","ONLY IN FLIGHT.","CONTINUOUSLY WHEN ELECTRICAL POWER IS AVAILABLE."],"correct":2,"explanation":"El extractor de lavatorios/galley funciona de forma continua siempre que haya energía eléctrica disponible, no solo en tierra ni solo en vuelo.","taughtIn":["air-11-c4"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:5ndqye"}}]},
{"id":"air-12","subject":"aire","order":12,"kind":"lesson","level":3,"ident":"MAN","title":"Manual pressurization","goal":"Explicar cómo se presuriza a mano si fallan los dos controladores y qué cuidados pide.","intro":"Si fallan los dos controladores, la tripulación mueve la outflow valve con un interruptor. Es lento y hay que mirar el V/S de cabina.","minutes":5,"cards":[{"id":"air-12-c1","title":"MODE SEL MAN","body":"Si fallan **los dos** controladores automáticos (CAB PR SYS 1+2 FAULT, con la luz FAULT del MODE SEL), la tripulación toma el control:\n- **MODE SEL en MAN:** corta la energía a los motores automáticos y habilita el **motor manual** de la outflow valve;\n- **MAN V/S CTL:** interruptor con resorte al centro; UP abre la válvula (la cabina sube) y DN la cierra (la cabina baja). Conviene darle toques cortos.","keyIdea":"MODE SEL en MAN habilita el motor manual; MAN V/S CTL lo mueve con toques cortos."},{"id":"air-12-c2","title":"Slow: watch the cabin V/S","body":"En manual la outflow valve se mueve **lento**: pueden pasar unos **10 segundos** hasta notar un cambio. Por eso se usa la indicación de **V/S de cabina** para confirmar que la válvula responde, y se vigilan seguido el V/S y la altitud de cabina.\n\nLas dos safety valves siguen limitando el ΔP a **8,6 PSI**. Por lo lento de la válvula, el procedimiento puede no evitar la despresurización, según la falla.","keyIdea":"En manual, unos 10 s de demora: confirmar con el V/S de cabina."},{"id":"air-12-c3","title":"Targets and landing","body":"El objetivo es subir la cabina a **500 ft/min** y bajarla a **300 ft/min**, con una altitud de cabina según el nivel de vuelo (por ejemplo, 8 000 ft a FL 390 y 5 500 ft a FL 300).\n\nEn la aproximación final, V/S CTL todo arriba, para que el ΔP llegue a cero. En manual la outflow valve **no se abre sola al aterrizar**: antes de abrir las puertas hay que confirmar que el ΔP sea **cero**.","diagram":{"alt":"Tabla de la presurización manual: altitud de cabina objetivo según el nivel de vuelo, 8 000 ft a FL 390, 7 000 a FL 350, 5 500 a FL 300, 3 000 a FL 250 y 0 bajo FL 200; V/S de cabina objetivo: 500 ft/min al subir y 300 ft/min al bajar.","src":"assets/estaciones/diagramas/air-manual.svg"},"keyIdea":"Cabina a 500 ft/min arriba y 300 abajo; al aterrizar, ΔP en cero antes de abrir puertas."}],"test":[{"id":"air-12-t1","type":"mcq","question":"En una falla de ambos cabin pressure controllers, ¿qué modo utiliza la tripulación para controlar la presurización?","options":["AUTO con LDG ELEV manual","MAN con MAN V/S CTL según sea necesario","DITCHING para modular el outflow valve","RAM AIR como control primario de presión"],"correct":1,"explanation":"Con los dos controladores fallados, la tripulación pone el MODE SEL en MAN y mueve la outflow valve con el MAN V/S CTL según haga falta.","taughtIn":["air-12-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:14giwzm"}},{"id":"air-12-t2","type":"mcq","question":"THE THIRD MOTOR (MANUAL) IN THE PRESSURIZATION SYSTEM IS ACTIVATED:","options":["AUTOMATICALLY IF BOTH AUTOMATIC MOTORS FAIL.","IN SEQUENCE AFTER EACH LANDING.","WHEN THE CABIN PRESS MODE SEL SWITCH IS POSITIONED TO MAN."],"correct":2,"explanation":"El tercer motor (manual) de la válvula de outflow se activa cuando el switch CABIN PRESS MODE SEL se posiciona en MAN, no automáticamente ante la falla de los dos motores automáticos ni en secuencia tras cada aterrizaje.","taughtIn":["air-12-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:ydcebr"}},{"id":"air-12-t3","type":"mcq","question":"¿Por qué conviene usar la indicación de cabin V/S al controlar manualmente la presurización?","options":["Por el retardo de respuesta del outflow valve","Porque cabin altitude deja de estar disponible","Porque el outflow valve queda bloqueado a 50 %","Porque el sistema manual controla los packs"],"correct":0,"explanation":"En manual la outflow valve responde lento: pueden pasar unos 10 segundos antes de notar el cambio. El V/S de cabina confirma que la orden está teniendo efecto y evita corregir de más.","taughtIn":["air-12-c2"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:195kvhu"}},{"id":"air-12-t4","type":"mcq","question":"¿Qué función de protección cumplen las safety valves del sistema de presurización?","options":["Limitan el diferencial de presión a 8.6 PSI","Mantienen el cabin altitude fijo en 8 000 ft","Cierran los packs al llegar a 1 PSI","Abren automáticamente RAM AIR"],"correct":0,"explanation":"Las dos safety valves limitan la diferencia de presión a 8,6 PSI; en presurización manual siguen protegiendo la estructura.","taughtIn":["air-12-c2"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:s0ruz4"}}]},
{"id":"air-13","subject":"aire","order":13,"kind":"lesson","level":3,"ident":"CAB","title":"Excess cabin altitude","goal":"Explicar cuándo aparece CAB PR EXCESS CAB ALT y las acciones del descenso de emergencia que lo siguen.","intro":"Una cabina que sube demasiado es una emergencia: primero el oxígeno, después el descenso.","minutes":5,"cards":[{"id":"air-13-c1","title":"When it triggers","body":"La alerta **CAB PR EXCESS CAB ALT** aparece cuando la altitud de cabina pasa de **9 550 ft** (en ascenso o descenso, de 9 550 ft o de 1 000 ft sobre el aeropuerto, lo que sea más alto). En la página CAB PRESS, la altitud de cabina destella desde 8 800 ft y pasa a rojo desde 9 550 ft.","keyIdea":"EXCESS CAB ALT: cabina sobre 9 550 ft."},{"id":"air-13-c2","title":"Masks and descent","body":"Sobre FL 100: **CREW OXY MASKS en USE**. Sobre FL 160, el EMER DESCENT:\n- SIGNS ON y **DESCENT INITIATE**;\n- si el A/THR no está activo, thrust levers en IDLE;\n- **SPD BRK FULL** (dejando que la velocidad aumente antes, para no activar la protección de ángulo de ataque);\n- **velocidad máxima apropiada** (MAX/APPROPRIATE; reducirla si se sospecha daño estructural);\n- ENG MODE SEL en IGN, avisar al ATC y a la cabina, y considerar 7700.\n\nEl objetivo: **FL 100 o la MEA-MORA**, la que sea más alta.","keyIdea":"Máscaras, descenso, SPD BRK FULL, velocidad máxima apropiada, hasta FL 100 o MEA-MORA."},{"id":"air-13-c3","title":"Oxygen and the outflow valve","body":"- **Oxígeno:** para ahorrarlo, el selector de dilución de las máscaras va a **N** (NORM). Si se deja en 100 %, el oxígeno puede no alcanzar para todo el descenso.\n- **Cabina sobre 14 000 ft:** PAX OXY MASKS en MAN ON.\n- **Outflow valve:** con el descenso establecido, si hay tiempo, revisar en la página CAB PRESS que la outflow valve esté cerrada. Si no lo está y el ΔP es positivo, elegir **el otro CPC**; si sigue sin cerrar, **MODE SEL en MAN** y ajustar el V/S CTL según la tabla.","keyIdea":"Diluter en N para ahorrar oxígeno; si la outflow valve no cierra: otro CPC y después MAN."}],"test":[{"id":"air-13-t1","type":"mcq","question":"AT WHAT CABIN ALTITUDE DO YOU GET AN ECAM WARNING?","options":["8,800 FEET.","9,000 FEET.","9,550 FEET.","14,000 FEET."],"correct":2,"explanation":"La alerta CAB PR EXCESS CAB ALT aparece con la altitud de cabina sobre 9 550 ft; en la página CAB PRESS, la altitud de cabina pasa a rojo desde ese valor.","taughtIn":["air-13-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:nfp1ur"}},{"id":"air-13-t2","type":"mcq","question":"Ante un EMER DESCENT, ¿qué posición se establece con los speed brakes y qué velocidad se usa una vez establecido el descenso?","options":["Speed brakes retraídos por completo; se mantiene la velocidad de crucero original","Speed brakes en HALF; velocidad mínima de maniobra","Speed brakes en FULL; velocidad MAX apropiada según la situación","Speed brakes según criterio del piloto; velocidad fija de 250 kt en todo momento"],"correct":2,"explanation":"En el descenso de emergencia: speed brakes en FULL y, una vez establecido el descenso, la velocidad máxima apropiada (MAX/APPROPRIATE), reduciéndola si se sospecha daño estructural.","taughtIn":["air-13-c2"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:h2m45k"}},{"id":"air-13-t3","type":"mcq","question":"Durante un EMER DESCENT, ¿a qué nivel de vuelo máximo (o referencia) apunta el descenso?","options":["FL 180 fijo, independiente del terreno o la zona geográfica sobrevolada","FL 100 o el MEA/MORA correspondiente, lo que sea mayor","FL 250, dejando un margen adicional de seguridad sobre el terreno","Nivel del mar, si la ruta lo permite"],"correct":1,"explanation":"El objetivo del descenso de emergencia es FL 100 o la MEA-MORA, la que sea más alta: la referencia de terreno manda cuando es más alta.","taughtIn":["air-13-c2"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:78kwo2"}},{"id":"air-13-t4","type":"mcq","question":"En el EMER DESCENT, ¿qué se hace con el selector de dilución de oxígeno (CREW OXY MASKS DILUTION) y por qué?","options":["Se deja en 100% durante todo el descenso, sin excepción","NORM, para conservar oxígeno durante el descenso","Se apaga completamente el suministro de oxígeno hasta nivelar en altitud segura","Se alterna cada 30 segundos entre NORM y 100% según indique el ECAM"],"correct":1,"explanation":"Se pasa el selector de dilución a N (normal) para ahorrar oxígeno: si se deja en 100 %, la cantidad puede no alcanzar para todo el descenso.","taughtIn":["air-13-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:4chv4g"}},{"id":"air-13-t5","type":"mcq","question":"Si tras un CAB PR EXCESS CAB ALT la outflow valve no cierra y el ΔP es positivo, ¿qué secuencia corresponde?","options":["Aterrizar de inmediato en el aeropuerto más cercano, sin ejecutar más pasos del procedimiento","Apagar ambos CPC simultáneamente y continuar el vuelo sin más intervención del sistema","Seleccionar el otro CPC; si no cierra, MAN y ajustar V/S CTL según la tabla","Abrir manualmente el RAM AIR antes de intentar el otro CPC"],"correct":2,"explanation":"El primer paso es intentar recuperar el control automático seleccionando el otro CPC (controlador de presurización). Si la válvula sigue sin cerrar, se pasa a control manual (MODE SEL en MAN), ajustando el V/S CTL hacia arriba o abajo según la tabla que relaciona el nivel de vuelo con la altitud de cabina objetivo (por ejemplo, FL390 → 8000 ft de cabina).","taughtIn":["air-13-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:1xc2ic3"}}]},
{"id":"air-repaso","subject":"aire","order":14,"kind":"review","level":3,"ident":"RAI","title":"Air conditioning and pneumatic review","goal":"Repasar el aire del avión de punta a punta: bleed, packs, temperatura, ram air, presurización y ventilación.","intro":"Llegamos al repaso: preguntas de todas las estaciones de aire acondicionado y neumático, incluidas algunas nuevas.","minutes":6,"cards":[{"id":"air-repaso-c1","title":"Pneumatic in one page","body":"- **Fuentes:** bleed de los motores (IP, o HP a baja potencia), APU y tierra HP.\n- **Bleed valve:** regula la presión (unos 45 PSI) y cierra por baja presión, reverse flow, el botón, el ENG FIRE pb o el BMC; el precooler enfría con aire del fan.\n- **APU BLEED ON:** abre el crossbleed, cierra los bleeds de motor; una check valve protege al APU.\n- **Fugas:** una fuga en un ala o pylon cierra la bleed valve de ese lado y el crossbleed (salvo en el arranque).","keyIdea":"IP o HP, bleed valve con su presión, APU con prioridad y check valve."},{"id":"air-repaso-c2","title":"Air conditioning in one page","body":"- **Packs:** air cycle machine; pack valve neumática con control eléctrico, cerrada sin aire; se cierra en el arranque.\n- **Caudal:** LO 80 %, NORM 100 %, HI 120 %; HI automático con un pack o con APU bleed.\n- **Temperatura:** tres zonas; los packs para la más fría y tres trim air valves con aire caliente; HOT AIR FAULT a 88 °C.\n- **Ram air:** humo o los dos packs; solo con ΔP bajo 1 PSI.","keyIdea":"Packs, caudal, tres zonas con trim air, ram air bajo 1 PSI."},{"id":"air-repaso-c3","title":"Pressurization in one page","body":"- **Piezas:** dos CPC (uno activo), una outflow valve con tres motores y dos safety valves (8,6 PSI y −1 PSI).\n- **Programa:** prepresurización en el despegue, cabina máxima de unos 8 000 ft, elevación y QNH del FMGS.\n- **Manual:** MODE SEL en MAN y MAN V/S CTL, con unos 10 s de demora.\n- **Alertas:** EXCESS CAB ALT sobre 9 550 ft; máscaras y descenso a FL 100 o MEA-MORA.\n- **Ditching:** cierra la outflow valve y las válvulas bajo la línea de flotación.","keyIdea":"Dos CPC, una outflow valve, 8 000 ft de cabina, 9 550 ft de alerta."}],"test":[{"id":"air-repaso-t1","type":"mcq","question":"WHAT IS THE MAX. NEGATIVE DIFF. PRESSURE FOR THE CABIN?","options":["0 PSI.","1 PSI.","2 PSI.","8.6 PSI."],"correct":1,"explanation":"La diferencial de presión negativa máxima de cabina es 1 PSI, el mismo valor que condiciona el uso seguro del ram air.","taughtIn":["air-repaso-c3","air-9-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:8qe7op"}},{"id":"air-repaso-t2","type":"mcq","question":"WITH THE PRESSURIZATION SYSTEM IN THE AUTOMATIC MODE, WHICH VALVES ARE CLOSED WHEN THE DITCHING PUSH BUTTON IS SELECTED ON?","options":["ALL VALVES BELOW THE WATER LINE.","APU INLET.","ONLY THE AVONICS COOLING VALVES.","THE ENGINE BLEED VALVES."],"correct":0,"explanation":"Al seleccionar DITCHING, se cierran todas las válvulas ubicadas por debajo de la línea de flotación, no solo la entrada del APU, las válvulas de enfriamiento de aviónica, o las de bleed de motor de forma aislada.","taughtIn":["air-repaso-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:7z1cpt"}},{"id":"air-repaso-t3","type":"mcq","question":"THE RAM AIR SWITCH SHOULD BE USED:","options":["AT ANY TIME.","ONLY WHEN DIFFERENTIAL PRESSURE IS LESS THAN 1 PSI.","WHEN DIFFERENTIAL PRESSURE IS MORE THAN 1 PSI.","ONLY AFTER OUTFLOW VALVE IS FULLY OPENED."],"correct":1,"explanation":"El switch de ram air solo debe usarse cuando la presión diferencial de cabina es menor a 1 PSI, una condición de seguridad para evitar abrirlo con presurización significativa aún presente.","taughtIn":["air-repaso-c2","air-8-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1b7mdi1"}},{"id":"air-repaso-t4","type":"mcq","question":"DURING NORMAL FLIGHT, THE AVIONICS VENTILATION SYSTEM CONTROLS THE TEMPERATURE OF THE COOLING AIR BY:","options":["ADDING AIR CONDITIONED AIR TO THE FLOW.","EXTRACTING AIR OVER BOARD.","ADDING A AVIONICS BAY AIR.","PASSING AIR THROUGH A SKIN HEAT EXCHANGER."],"correct":3,"explanation":"En vuelo normal (circuito cerrado), la temperatura del aire de enfriamiento de aviónica se controla haciéndolo pasar por un intercambiador de calor con el fuselaje (skin heat exchanger), no agregando aire acondicionado ni extrayendo al exterior.","taughtIn":["air-11-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:ei8m7j"}},{"id":"air-repaso-t5","type":"mcq","question":"Al seleccionar APU BLEED ON con el APU disponible, ¿qué sucede normalmente con el crossbleed?","options":["La lógica puede abrirlo automáticamente para distribuir APU bleed","Permanece siempre cerrado salvo selección manual OPEN","Cierra obligatoriamente para impedir que el APU alimente ambos packs","Transfiere solamente presión hidráulica entre Green y Yellow"],"correct":0,"explanation":"El APU puede alimentar la red neumática común. Con crossbleed en AUTO, la presencia de APU bleed provoca la apertura necesaria para distribuir ese aire.","taughtIn":["air-repaso-c1","air-3-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:c31by2"}},{"id":"air-repaso-t6","type":"mcq","question":"¿Qué protección actúa ante un duct overheat del sistema HOT AIR?","options":["El pack flow aumenta automáticamente para enfriar el duct afectado","Cierran la hot air pressure regulating valve y los trim air valves","RAM AIR abre automáticamente para descargar el aire caliente overboard","El outflow valve cierra para evitar que el calor llegue a la cabina"],"correct":1,"explanation":"Con duct overheat (88 °C), se cierran solas la hot air pressure regulating valve y las trim air valves, y se enciende la luz FAULT del HOT AIR.","taughtIn":["air-repaso-c2","air-7-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:1d61doo"}},{"id":"air-repaso-t7","type":"mcq","question":"¿A qué condición de temperatura vuelve el Fan Speed Controller a low speed?","options":["Por debajo de 35 °C","Por debajo de 40 °C","Al apagar ambos motores","Bajo 8000 ft de cabina"],"correct":0,"explanation":"Existe histéresis entre los puntos de high y low speed para evitar cambios repetitivos: high sobre 40 °C y low bajo 35 °C.","taughtIn":["air-11-c1"],"source":{"bank":"fcom","system":"air_cond","appId":"air_cond:c42mx4"}}]}
]};
